$questions = [
    // [101] Brasil Colônia e Economia Açucareira
    [101, 'ENEM 2023', 'Durante o período colonial brasileiro, a principal atividade econômica do Nordeste nos séculos XVI e XVII estava fundamentada em qual base estrutural?', 'a produção de açúcar nos engenhos, baseada no latifúndio e na mão de obra escravizada', 'a mineração de ouro em Minas Gerais sustentada por trabalhadores livres', 'a exportação de café cultivado no sistema de plantation europeu', 'o comércio de especiarias asiáticas utilizando portos nordestinos', 'a pecuária extensiva que servia como mercado exportador', 'a', 'A economia açucareira se baseava no sistema de plantation: grandes propriedades (latifúndios), monocultura, mão de obra escravizada e produção voltada para a exportação.', 'fácil', 0],
    [101, 'UNICAMP 2022', 'A ocupação holandesa no Nordeste brasileiro (1630-1654) esteve diretamente relacionada a qual contexto europeu?', 'À União Ibérica e aos conflitos da Espanha com os Países Baixos, o que levou ao embargo do comércio de açúcar.', 'À aliança política entre Portugal e França para combater a Inglaterra no Atlântico Sul.', 'Ao declínio do Império Britânico que buscou refugiar-se nas colônias portuguesas.', 'Aos interesses exclusivos da Companhia das Índias Orientais em monopolizar o tráfico negreiro.', 'À crise do sistema feudal europeu, que forçou a migração de holandeses para as Américas.', 'a', 'Com a União Ibérica (1580-1640), os inimigos da Espanha, como a Holanda, tornaram-se inimigos de Portugal. A Espanha proibiu o comércio açucareiro com os holandeses, que então invadiram o Nordeste.', 'médio', 0],
    [101, 'USP (FUVEST) 2021', 'A mão de obra indígena foi amplamente utilizada nos primeiros anos de colonização no Brasil, mas gradativamente substituída pela africana na economia açucareira. Um dos principais motivos para isso foi:', 'a alta lucratividade do tráfico negreiro, que beneficiava a Coroa portuguesa e os mercadores.', 'a falta de adaptação física dos indígenas ao trabalho na lavoura de subsistência.', 'a forte proteção aos indígenas garantida pela bula papal que proibia sua escravização sob qualquer hipótese.', 'a aliança militar entre tribos tupis e os corsários franceses que expulsaram os portugueses do litoral.', 'o total esgotamento da população nativa já no final do século XVI devido a guerras locais.', 'a', 'O tráfico transatlântico de escravizados africanos era um negócio extremamente lucrativo, gerando impostos para a Coroa e lucros para os comerciantes metropolitanos, diferentemente do escravismo indígena.', 'médio', 0],
    [101, 'UNESP 2023', 'As Câmaras Municipais no Brasil Colônia exerciam papel fundamental na administração local. Eram compostas pelos "homens bons", que se caracterizavam por ser:', 'proprietários de terras e escravizados, com pureza de sangue e católicos, excluindo trabalhadores manuais.', 'representantes eleitos democraticamente por todos os habitantes livres da vila.', 'nomeados diretamente pelo rei de Portugal para fiscalizar os governadores-gerais.', 'clérigos e militares responsáveis pela defesa militar da capitania.', 'comerciantes reinóis recém-chegados que detinham o monopólio mercantil.', 'a', 'Os "homens bons" eram a elite local: senhores de terras e escravos. Trabalhadores manuais, judeus e negros não podiam participar.', 'fácil', 0],
    [101, 'USP (FUVEST) 2024', 'As capitanias hereditárias, implantadas em 1534, foram o primeiro modelo administrativo no Brasil. Sobre seu fracasso parcial, é correto afirmar que ocorreu devido:', 'à falta de recursos da maioria dos donatários e aos constantes ataques de populações indígenas.', 'à concorrência direta do açúcar produzido nas Antilhas inglesas no século XVI.', 'ao desinteresse de Portugal, que lucrava mais com o comércio exclusivo do pau-brasil no litoral.', 'à revolta dos colonos que exigiam um sistema representativo republicano.', 'à escassez de terras férteis no litoral brasileiro para a plantação de cana-de-açúcar.', 'a', 'O sistema das capitanias enfrentou grandes dificuldades: muitos donatários não tinham capital para investir, a distância da metrópole dificultava o apoio e a resistência indígena impedia a ocupação.', 'difícil', 1],

    // [102] Mineração e Inconfidências no Brasil
    [102, 'ENEM 2022', 'A descoberta de ouro em Minas Gerais no século XVIII transformou a configuração colonial. Uma consequência direta da mineração foi:', 'o deslocamento do eixo econômico para o Centro-Sul e a mudança da capital para o Rio de Janeiro.', 'a descentralização administrativa com a extinção do cargo de vice-rei no Brasil.', 'a abolição precoce da escravidão na região das minas devido ao trabalho livre dos faiscadores.', 'a estagnação urbana, já que a população se dispersou em latifúndios isolados.', 'o fim do Pacto Colonial, permitindo livre comércio com a Inglaterra.', 'a', 'A mineração atraiu a população para o Centro-Sul, gerou urbanização e levou o Marquês de Pombal a mudar a capital de Salvador para o Rio de Janeiro em 1763, porto de escoamento do ouro.', 'fácil', 0],
    [102, 'UNICAMP 2023', 'A Inconfidência Mineira (1789) e a Conjuração Baiana (1798) foram movimentos emancipacionistas com perfis distintos. Diferentemente da revolta mineira, a baiana:', 'teve forte participação popular, incluindo escravizados e libertos, defendendo o fim da escravidão.', 'tinha caráter monarquista, propondo a coroação de D. João VI como imperador do Brasil.', 'foi apoiada militarmente e financeiramente por tropas de Napoleão Bonaparte.', 'teve sucesso em separar a província, que se manteve independente por uma década.', 'limitou-se a exigir a isenção da Derrama, sem propor a separação de Portugal.', 'a', 'A Conjuração Baiana (Revolta dos Alfaiates) foi um movimento popular e abolicionista, influenciado pela Revolução Francesa, enquanto a Inconfidência Mineira foi elitista e não propôs o fim da escravidão.', 'médio', 0],
    [102, 'USP (FUVEST) 2022', 'O sistema de tributação imposto pela Coroa portuguesa na região das Minas Gerais incluía a arrecadação de um quinto do ouro extraído. A instituição criada para controlar a fundição e a cobrança de impostos foi:', 'as Casas de Fundição, onde o ouro em pó era proibido e transformado em barras seladas.', 'as Intendências das Minas, controladas exclusivamente pelo clero católico local.', 'o Conselho Ultramarino, responsável apenas por taxar os diamantes.', 'a Companhia de Jesus, que monopolizava a extração nas terras indígenas.', 'as Câmaras Municipais, que dividiam os lucros das lavras com o rei.', 'a', 'Para combater o contrabando do ouro em pó, a Coroa estabeleceu as Casas de Fundição em 1720, que derretiam o ouro, retiravam o "quinto" real e devolviam o resto em barras seladas.', 'médio', 0],
    [102, 'UNESP 2021', 'A sociedade mineradora mineira do século XVIII apresentava uma estrutura social diferente da nordestina açucareira. Ela caracterizava-se por ser:', 'mais urbana e com maior fluidez social, permitindo a existência de uma camada média expressiva.', 'estritamente rural, dominada pelos senhores de engenho e sem classes médias.', 'completamente igualitária, pois a abundância de ouro erradicou a pobreza livre.', 'formada exclusivamente por trabalhadores assalariados vindos da metrópole.', 'dominada pela nobreza feudal portuguesa que migrou em massa para administrar as minas.', 'a', 'A mineração exigiu comércio, serviços e artesanato, criando vilas ricas e uma classe média urbana (comerciantes, militares, profissionais liberais), propiciando maior mobilidade social que no Nordeste rural.', 'fácil', 0],
    [102, 'USP (FUVEST) 2023', 'A decretação da Derrama pela Coroa Portuguesa foi o estopim idealizado pelos inconfidentes em 1789. A Derrama consistia:', 'na cobrança compulsória dos impostos atrasados para atingir a meta anual de 100 arrobas de ouro.', 'no monopólio estatal sobre o comércio de escravizados na região do Rio das Velhas.', 'na expulsão dos jesuítas e confisco de seus bens na capitania de Minas Gerais.', 'na proibição de manufaturas têxteis no Brasil, o que arruinou os alfaiates mineiros.', 'no recrutamento forçado de brasileiros para lutarem nas guerras napoleônicas na Europa.', 'a', 'A Derrama era a cobrança de impostos em atraso quando a região não alcançava a cota fixa anual de 100 arrobas (1500 kg) de ouro devida à metrópole. Podia envolver o confisco de bens da população.', 'difícil', 1],

    // [103] Brasil Império e Independência
    [103, 'ENEM 2021', 'A transferência da Corte portuguesa para o Brasil em 1808 causou profundas transformações. A Abertura dos Portos às Nações Amigas, primeira medida tomada por D. João VI, significou na prática:', 'o fim do monopólio comercial metropolitano (Pacto Colonial) sobre o Brasil.', 'a consolidação das alianças comerciais exclusivas com a França napoleônica.', 'o fechamento do Brasil para o comércio inglês, causando grave crise econômica.', 'a proibição do tráfico de escravizados devido à pressão da Inglaterra.', 'a autonomia política completa e imediata do Brasil, declarando a República.', 'a', 'A Abertura dos Portos rompeu o pacto colonial, permitindo que o Brasil comercializasse livremente com outras nações (especialmente a Inglaterra), sendo o primeiro passo prático rumo à independência.', 'fácil', 0],
    [103, 'UNICAMP 2024', 'A Constituição de 1824, outorgada por D. Pedro I, estabelecia a divisão do governo em quatro poderes. O Poder Moderador tinha a função de:', 'garantir o equilíbrio entre os poderes, sendo exercido exclusivamente pelo Imperador para intervir no Legislativo e Executivo.', 'julgar os crimes comuns e políticos da nobreza, atuando como Suprema Corte imperial.', 'representar as províncias através de presidentes eleitos pelo voto direto universal.', 'controlar as Forças Armadas e declarar guerras sem a necessidade de aprovação da Assembleia.', 'garantir o direito de voto aos escravizados libertos e às mulheres da elite.', 'a', 'Inspirado por Benjamin Constant, o Poder Moderador, exclusivo do Imperador, estava acima dos poderes Executivo, Legislativo e Judiciário, conferindo a D. Pedro I poderes absolutistas mascarados de liberalismo.', 'médio', 0],
    [103, 'USP (FUVEST) 2020', 'O período regencial (1831-1840) foi marcado por grande instabilidade política e diversas revoltas provinciais. A Revolução Farroupilha (1835-1845), ocorrida no sul do país, teve como principal motivação econômica:', 'a insatisfação dos estancieiros gaúchos com os altos impostos sobre o charque nacional, que favoreciam a importação platina.', 'o desejo de abolir a escravidão nas lavouras de café que se expandiam no Rio Grande do Sul.', 'a luta pelo controle das ricas minas de ouro e diamante recém-descobertas na região de Santa Catarina.', 'a resistência contra o recrutamento obrigatório para a Guerra do Paraguai imposta pelas regências.', 'o movimento camponês em defesa da reforma agrária em latifúndios improdutivos no pampa.', 'a', 'Os grandes criadores de gado e produtores de charque (estancieiros) rebelaram-se contra os altos impostos alfandegários do Império, que tornavam o charque gaúcho mais caro que o importado do Uruguai e Argentina.', 'médio', 0],
    [103, 'UNESP 2022', 'A Lei de Terras de 1850, promulgada semanas após a Lei Eusébio de Queirós, determinou que:', 'as terras devolutas só poderiam ser adquiridas por compra e venda, dificultando o acesso de ex-escravos e imigrantes pobres à propriedade.', 'as vastas propriedades improdutivas fossem desapropriadas para a distribuição gratuita aos imigrantes italianos.', 'todas as áreas indígenas fossem demarcadas e protegidas pela Coroa contra os cafeicultores.', 'as posses de terras fossem legalizadas gratuitamente, consolidando a pequena propriedade no Sudeste.', 'os ex-escravizados recebessem lotes de terra como indenização pelos anos de trabalho forçado.', 'a', 'A Lei de Terras proibiu a obtenção de terras por ocupação (posse), exigindo a compra do Estado. Isso garantiu que os imigrantes e libertos trabalhassem nas fazendas da elite, em vez de se tornarem pequenos proprietários.', 'difícil', 1],
    [103, 'ENEM 2019', 'O Golpe da Maioridade (1840), que antecipou a coroação de D. Pedro II aos 14 anos, foi uma manobra política liderada pelo Partido Liberal com o objetivo de:', 'restaurar a estabilidade política e conter as diversas rebeliões provinciais do período regencial.', 'instaurar a República e depor a família real dos Bragança definitivamente.', 'aprovar imediatamente leis abolicionistas e promover a industrialização do país.', 'centralizar o poder nas mãos dos regentes militares paulistas.', 'garantir o direito de voto aos analfabetos na constituição do Império.', 'a', 'O Golpe da Maioridade buscou pacificar o país em meio às revoltas regenciais, usando a figura do jovem imperador como símbolo de unidade nacional e autoridade para restabelecer a ordem.', 'fácil', 0],

    // [104] República Velha e Era Vargas
    [104, 'ENEM 2023', 'A política dos governadores, idealizada no governo Campos Sales, consistia fundamentalmente em:', 'uma aliança entre o governo federal e as oligarquias estaduais, garantindo apoio mútuo e fraudes eleitorais para manter os mesmos grupos no poder.', 'um sistema de rodízio na presidência exclusivo entre os governadores de Minas Gerais, São Paulo e Rio Grande do Sul.', 'um mecanismo constitucional que permitia aos governadores estaduais vetarem decisões econômicas do Presidente da República.', 'uma política de reforma agrária coordenada pelos estados para atender às demandas de movimentos como Canudos.', 'um pacto militar que colocava o exército nacional subordinado aos governadores para reprimir as greves operárias.', 'a', 'Foi a base política da República Oligárquica: o presidente não interferia nos estados, apoiando as oligarquias locais (coronelismo), que, em troca, usavam fraudes para eleger deputados favoráveis ao presidente.', 'fácil', 0],
    [104, 'UNICAMP 2021', 'A Revolta da Vacina (1904) ocorreu no Rio de Janeiro durante o governo de Rodrigues Alves. Entre as causas do movimento popular, destacam-se:', 'a imposição da vacinação obrigatória contra varíola associada ao autoritarismo das reformas urbanas (bota-abaixo) que expulsou os pobres do centro.', 'a proibição de cultos de matriz africana e a perseguição policial a imigrantes europeus na cidade.', 'a falta de eficácia da vacina, que na verdade transmitia a febre amarela para a população pobre.', 'o aumento exorbitante das tarifas de transporte público gerido por empresas estrangeiras no Rio de Janeiro.', 'a recusa dos marinheiros em aceitarem os castigos corporais combinada à obrigatoriedade da vacina.', 'a', 'O sanitarista Oswaldo Cruz impôs a vacina obrigatória sem campanha de conscientização. A população, já revoltada com o custo de vida e a reforma urbana que destruiu os cortiços, rebelou-se nas ruas.', 'médio', 0],
    [104, 'USP (FUVEST) 2023', 'A Revolução de 1930 marcou o fim da Primeira República. O principal motivo que levou a Aliança Liberal, liderada por Getúlio Vargas, a tomar o poder foi:', 'o rompimento do acordo do café com leite e a recusa de Washington Luís em apoiar o candidato mineiro à presidência, agravados pelo assassinato de João Pessoa.', 'a pressão do Partido Comunista Brasileiro (PCB) para instaurar um regime socialista no sul do país.', 'a falência massiva dos cafeicultores devido à queima de estoques promovida pelos paulistas.', 'o golpe militar liderado pelo Tenentismo que exigia o fechamento imediato do Congresso.', 'a fraude nas eleições de 1930 que deu vitória a Vargas, contestada pelas armas por São Paulo.', 'a', 'Em 1930, Washington Luís (paulista) apoiou Júlio Prestes (paulista) em vez do candidato de MG (Antônio Carlos). MG, RS e PB uniram-se na Aliança Liberal. Após a derrota nas urnas (fraudadas) e a morte de João Pessoa, iniciaram a revolução.', 'médio', 0],
    [104, 'UNESP 2024', 'Durante o Estado Novo (1937-1945), Getúlio Vargas criou o Departamento de Imprensa e Propaganda (DIP). Sua função primordial era:', 'censurar os meios de comunicação e promover a exaltação da figura do ditador e do nacionalismo.', 'garantir a liberdade de imprensa e subsidiar jornais de oposição para manter uma fachada democrática.', 'organizar as eleições regulares para o Congresso e propagar os resultados nas rádios.', 'promover o comunismo nos sindicatos por meio da distribuição de cartilhas aos trabalhadores.', 'investigar e prender integralistas que conspiravam contra o governo nas áreas rurais.', 'a', 'O DIP era o órgão de censura e propaganda oficial da ditadura do Estado Novo. Ele censurava rádio, jornais e cinema, enquanto criava programas como a "Hora do Brasil" para glorificar Vargas como "Pai dos Pobres".', 'fácil', 0],
    [104, 'USP (FUVEST) 2022', 'A Consolidação das Leis do Trabalho (CLT), promulgada por Vargas em 1943, reuniu a legislação trabalhista brasileira. Essa ação governamental inseria-se na política do corporativismo e do populismo, caracterizando-se por:', 'conceder direitos aos trabalhadores urbanos atrelando os sindicatos ao controle estrito do Estado, esvaziando a luta autônoma de classes.', 'estender amplos direitos aos camponeses, promovendo a reforma agrária e combatendo o coronelismo no interior.', 'adotar políticas neoliberais, flexibilizando os direitos trabalhistas para atrair indústrias multinacionais.', 'criar conselhos operários independentes que geriam as fábricas juntamente com os patrões.', 'legalizar o direito incondicional de greve e fortalecer os sindicatos anarquistas que lideravam o movimento operário.', 'a', 'Vargas utilizou a legislação trabalhista (trabalhismo/populismo) para cooptar as massas urbanas. A CLT concedeu direitos (férias, salário mínimo), mas atrelou os sindicatos ao Ministério do Trabalho (peleguismo), impedindo greves independentes.', 'difícil', 1],

    // [105] Ditadura Militar e Redemocratização
    [105, 'ENEM 2023', 'O Ato Institucional nº 5 (AI-5), decretado em dezembro de 1968, é considerado o instrumento mais duro da Ditadura Militar brasileira porque:', 'deu plenos poderes ao Executivo para fechar o Congresso Nacional, cassar mandatos e suspender o habeas corpus para crimes políticos.', 'estabeleceu o pluripartidarismo, permitindo a criação de legendas de esquerda sob rígida vigilância militar.', 'anistiou todos os presos políticos exilados, mas baniu os líderes estudantis envolvidos em passeatas.', 'iniciou a abertura lenta, gradual e segura sob o comando do general Ernesto Geisel.', 'censurou exclusivamente as obras estrangeiras, protegendo a cultura nacionalista nas rádios.', 'a', 'O AI-5 inaugurou os "Anos de Chumbo". O presidente ganhou poder absoluto para fechar o Congresso, intervir nos estados, cassar políticos, demitir juízes e suspender o habeas corpus (garantia contra prisões arbitrárias).', 'fácil', 0],
    [105, 'UNICAMP 2022', 'A campanha das Diretas Já (1983-1984) mobilizou milhões de brasileiros. Seu objetivo imediato e seu desfecho foram, respectivamente:', 'a aprovação da Emenda Dante de Oliveira para eleições presidenciais diretas; a emenda foi rejeitada pelo Congresso.', 'a destituição do general Figueiredo; a renúncia do ditador e a eleição popular de Tancredo Neves.', 'a convocação de uma Assembleia Constituinte; a aprovação imediata de uma nova constituição democrática.', 'a anistia ampla e irrestrita; a volta de todos os exilados políticos ao Brasil com direitos políticos.', 'a eleição direta para governadores de estado; a vitória esmagadora do PMDB nas capitais.', 'a', 'O movimento pedia a aprovação da Emenda Constitucional Dante de Oliveira (eleições diretas para presidente). A emenda não obteve os 2/3 dos votos no Congresso e foi rejeitada. A eleição de 1985 foi indireta (Tancredo Neves).', 'médio', 0],
    [105, 'USP (FUVEST) 2021', 'A Constituição de 1988, chamada de "Constituição Cidadã", representou o marco jurídico da redemocratização. Entre suas inovações no campo dos direitos políticos e sociais, destaca-se:', 'a instituição do voto facultativo para analfabetos e jovens de 16 e 17 anos, e a criação do Sistema Único de Saúde (SUS).', 'a exclusão do direito de greve para servidores públicos e a privatização de empresas estatais de telefonia.', 'o restabelecimento da monarquia parlamentarista, decidida após o plebiscito convocado no mesmo ano.', 'a adoção do bipartidarismo estrito para evitar a pulverização partidária que causou o golpe de 64.', 'a submissão do poder Judiciário às decisões dos conselhos populares de bairro.', 'a', 'A Carta de 1988 ampliou imensamente a cidadania: concedeu voto a analfabetos (facultativo), criou o SUS universal, garantiu o direito de greve, licença maternidade de 120 dias e o pluripartidarismo.', 'médio', 0],
    [105, 'UNESP 2020', 'Durante a Ditadura Civil-Militar (1964-1985), ocorreu o "Milagre Econômico" (1968-1973). Economicamente, esse período foi marcado por:', 'altas taxas de crescimento do PIB, forte endividamento externo e acentuada concentração de renda.', 'estabilidade inflacionária alcançada pelo congelamento de preços e distribuição de terras para reforma agrária.', 'redução da dívida externa nacional e aumento expressivo do salário mínimo real dos trabalhadores.', 'nacionalização de indústrias automobilísticas estrangeiras e autossuficiência na produção de petróleo.', 'estagnação do crescimento econômico compensada pela erradicação da pobreza extrema no Nordeste.', 'a', 'O "Milagre" liderado pelo ministro Delfim Netto gerou crescimento de até 10% ao ano financiado por empréstimos externos, mas achatou salários ("fazer o bolo crescer para depois dividir"), aprofundando a desigualdade social.', 'fácil', 0],
    [105, 'USP (FUVEST) 2024', 'A Lei da Anistia, promulgada em 1979 no governo João Figueiredo, foi resultado de intensa pressão da sociedade civil. O texto da lei, porém, gerou e ainda gera debates jurídicos, pois:', 'foi uma anistia recíproca (ampla, geral e irrestrita), perdoando tanto opositores que cometeram crimes políticos quanto agentes do Estado envolvidos em tortura.', 'excluiu de forma explícita todos os exilados que haviam pegado em armas, permitindo apenas a volta de intelectuais e artistas.', 'permitiu que militares acusados de tortura fossem julgados imediatamente em cortes internacionais de direitos humanos.', 'obrigou o Estado a pagar pesadas indenizações exclusivamente aos líderes dos partidos de oposição moderada.', 'limitou o retorno dos exilados políticos até a aprovação da nova Constituição em 1988.', 'a', 'A anistia aprovada não puniu ninguém. O regime garantiu que os militares e agentes policiais que praticaram tortura, assassinatos e desaparecimentos (crimes de Estado) não fossem julgados, interpretando que a lei os perdoava também.', 'difícil', 1],

    // [106] Antiguidade Clássica: Grécia e Roma
    [106, 'ENEM 2022', 'Em Atenas, no século V a.C., consolidou-se um regime democrático. A democracia ateniense caracterizava-se por ser:', 'direta e restrita, limitando a participação política apenas a homens adultos, nascidos em Atenas, livres e proprietários de terras.', 'representativa e universal, garantindo o direito de voto a homens, mulheres e metecos (estrangeiros).', 'baseada na eleição de senadores vitalícios que controlavam as finanças e o exército da cidade-estado.', 'militarista, em que a cidadania era concedida apenas aos soldados aprovados nos treinamentos rigorosos do Estado.', 'censitária, permitindo o voto apenas para os grandes comerciantes marítimos que pagassem altos impostos.', 'a', 'A democracia em Atenas era direta (os cidadãos votavam as leis na Eclésia), porém excludente: mulheres, escravos e estrangeiros (metecos) não eram considerados cidadãos e não participavam da política.', 'fácil', 0],
    [106, 'UNICAMP 2023', 'As Guerras Púnicas (264-146 a.C.) foram travadas entre Roma e Cartago. O principal resultado desses conflitos para a República Romana foi:', 'a hegemonia sobre o Mar Mediterrâneo, o enorme afluxo de escravos e a expansão dos grandes latifúndios rurais.', 'a derrota completa das legiões romanas, forçando o Senado a ceder a Península Ibérica aos cartagineses.', 'o estabelecimento da Pax Romana imediata e o fim de todas as disputas políticas internas envolvendo patrícios e plebeus.', 'a adoção do monoteísmo cristão pelas tropas veteranas que retornaram do norte da África.', 'a transição pacífica e voluntária da República para o Império sob a liderança do general Aníbal.', 'a', 'Roma destruiu Cartago, passando a dominar o "Mare Nostrum" (Mediterrâneo). As riquezas e os prisioneiros de guerra (escravos) levaram à concentração de terras nas mãos da elite patrícia e ao empobrecimento da plebe.', 'médio', 0],
    [106, 'USP (FUVEST) 2021', 'Esparta diferenciou-se das demais cidades-estado gregas devido à sua rígida estrutura social e política. A sociedade espartana apoiava-se fundamentalmente:', 'na exploração do trabalho dos ilotas, que pertenciam ao Estado, e na dedicação exclusiva dos cidadãos (esparciatas) à guerra.', 'na intensa atividade mercantil marítima e no comércio de cerâmicas finas por todo o Mediterrâneo.', 'na valorização das artes, filosofia e arquitetura monumental financiada pela Liga de Delos.', 'na constante mobilidade social promovida pelos legisladores como Sólon e Clístenes.', 'na formação de uma federação democrática onde periecos e ilotas possuíam direitos políticos plenos.', 'a', 'Esparta era oligárquica e militarista. Os cidadãos (esparciatas) eram soldados e proprietários de terras, que eram trabalhadas obrigatoriamente pelos ilotas (servos do Estado em condições análogas à escravidão).', 'médio', 0],
    [106, 'UNESP 2022', 'Os irmãos Tibério e Caio Graco foram tribunos da plebe no século II a.C. em Roma. Seus projetos políticos focavam principalmente na:', 'reforma agrária, visando distribuir terras públicas aos camponeses pobres para diminuir a desigualdade e fortalecer o exército.', 'expansão territorial em direção às Gálias para obter mais ouro e pagar as dívidas externas romanas.', 'construção de coliseus e aquedutos para implementar a política do "Pão e Circo".', 'elevação de escravos libertos à condição de senadores e generais das legiões.', 'aprovação da Lei das Doze Tábuas para garantir o casamento igualitário entre patrícios e plebeus.', 'a', 'Os irmãos Graco tentaram combater a crise social na República propondo a Lei Agrária (limite de terras públicas e distribuição à plebe) e a Lei Frumentária (trigo subsidiado). Ambos foram assassinados pela elite patrícia.', 'fácil', 0],
    [106, 'USP (FUVEST) 2024', 'A passagem da República para o Império em Roma envolveu uma série de guerras civis e concentração de poder. O governo de Otávio Augusto (27 a.C. - 14 d.C.) consolidou essa transição ao:', 'manter as fachadas das instituições republicanas (como o Senado), esvaziando-as de poder e concentrando os títulos de imperador, príncipe e sumo pontífice.', 'abolir formalmente o Senado Romano e instaurar uma monarquia absolutista de direito divino sem eleições magistrais.', 'promover a divisão imediata do Império em Ocidente e Oriente para facilitar a administração das províncias conquistadas.', 'conceder cidadania romana plena e universal a todos os habitantes do Império, incluindo bárbaros submetidos.', 'estabelecer o cristianismo como religião oficial do Estado, perseguindo os cultos politeístas tradicionais.', 'a', 'Otávio Augusto foi astuto: não se declarou rei, preservou o Senado, os cônsules e tribunos na aparência, mas concentrou todo o controle do exército, do erário e das leis em suas mãos, iniciando o Principado.', 'difícil', 1],

    // [107] Feudalismo e Idade Média
    [107, 'ENEM 2023', 'A economia feudal da Europa Ocidental durante a Alta Idade Média baseava-se predominantemente:', 'na agricultura de subsistência, realizada nos feudos, com escassa circulação monetária e comércio restrito a trocas locais.', 'na produção em larga escala de manufaturas exportadas pelas guildas marítimas italianas.', 'na cobrança de altos impostos em moedas de ouro pelos reis absolutos sobre os senhores feudais.', 'na exploração intensa de rotas terrestres de seda e especiarias asiáticas coordenadas pelos monges.', 'na formação de companhias comerciais burguesas que financiaram as Cruzadas.', 'a', 'O feudalismo caracterizava-se por unidades agrícolas autossuficientes (senhorios ou feudos). A economia era agrária e amonetária (uso de trocas in natura). O comércio urbano desapareceu quase por completo nesse período.', 'fácil', 0],
    [107, 'UNICAMP 2022', 'As relações de suserania e vassalagem eram essenciais para a estrutura política do feudalismo. Elas consistiam em:', 'alianças militares e de fidelidade mútua entre nobres, nas quais o suserano doava terras (feudo) ao vassalo, que em troca oferecia auxílio militar e conselho.', 'obrigações de trabalho forçado impostas pelos cavaleiros cristãos sobre os servos camponeses muçulmanos.', 'acordos comerciais entre as nascentes monarquias europeias e o papado visando à conquista de Jerusalém.', 'contratos de arrendamento de feudos celebrados entre os bispos e os burgueses enriquecidos das cidades.', 'submissão total de todos os duques e condes ao poder absolutista do rei, que governava de forma centralizada.', 'a', 'Suserania e vassalagem eram vínculos horizontais (entre nobres). O suserano concede o benefício (terra) e o vassalo presta homenagem (fidelidade militar). Isso gerou a fragmentação do poder político.', 'médio', 0],
    [107, 'USP (FUVEST) 2021', 'As Cruzadas (séculos XI ao XIII), convocadas pela Igreja Católica, tiveram múltiplas motivações e consequências. Uma importante consequência econômica das Cruzadas foi:', 'o renascimento comercial e urbano na Europa Ocidental, com a reabertura do Mar Mediterrâneo ao comércio europeu.', 'a destruição total das rotas comerciais islâmicas, levando ao fim das trocas entre Oriente e Ocidente.', 'o fortalecimento imediato do sistema feudal devido à grande quantidade de terras conquistadas na Ásia Menor.', 'o fechamento das universidades europeias para evitar o contágio com o pensamento aristotélico trazido pelos árabes.', 'a conversão forçada de todos os judeus e muçulmanos do Mediterrâneo oriental ao catolicismo.', 'a', 'Ao tentarem reconquistar a Terra Santa, os cruzados restabeleceram contatos comerciais entre a Europa e o Oriente Médio, enfraquecendo as estruturas feudais e impulsionando a burguesia das cidades italianas (Gênova e Veneza).', 'médio', 0],
    [107, 'UNESP 2024', 'No contexto do senhorio feudal, os camponeses (servos) estavam presos à terra e deviam diversas obrigações ao senhor. A corveia e a talha eram, respectivamente:', 'trabalho gratuito e obrigatório nas terras do senhor; e a entrega de parte da produção agrícola cultivada no lote do servo.', 'o pagamento por uso do moinho do senhor; e o imposto anual cobrado pela Igreja Católica.', 'o recrutamento para as milícias em tempo de guerra; e a obrigação de hospedar o senhor e sua comitiva.', 'o imposto pago em moedas de prata; e o dízimo destinado aos monastérios locais.', 'a prestação de juramento de vassalagem; e a entrega do primogênito para as ordens da cavalaria.', 'a', 'A corveia era o trabalho compulsório (geralmente 3 dias por semana) no manso senhorial. A talha era a porcentagem da colheita do manso servil entregue ao senhor como aluguel da terra.', 'fácil', 0],
    [107, 'USP (FUVEST) 2023', 'A crise do século XIV marcou o declínio do feudalismo na Europa. Essa crise foi uma conjugação catastrófica de três fatores principais, conhecidos como a tríade da crise medieval:', 'a Grande Fome causada por más colheitas, a pandemia de Peste Negra e os conflitos prolongados como a Guerra dos Cem Anos.', 'a invasão dos hunos, o Cisma do Oriente e a Revolução de Avis em Portugal.', 'a escassez de ouro vindo das Américas, a revolta dos camponeses na Rússia e as Cruzadas Albigenses.', 'o surgimento da Reforma Protestante, a queda de Constantinopla e a Inquisição Espanhola.', 'a excomunhão dos reis francos, a rebelião dos vassalos ingleses e o esgotamento das minas de prata germânicas.', 'a', 'A virada do século XIII para o XIV enfrentou saturação de terras agrícolas (Fome de 1315), a letal Peste Bubônica (1347, que matou 1/3 da Europa) e guerras mortais (Inglaterra x França). Esse colapso demográfico forçou o fim da servidão.', 'difícil', 1],

    // [108] Revoluções Industriais e Iluminismo
    [108, 'ENEM 2022', 'O Iluminismo, movimento intelectual do século XVIII, tinha como pilares fundamentais:', 'a valorização da razão como via para o progresso, a crítica ao absolutismo monárquico e a defesa dos direitos naturais, como liberdade e propriedade.', 'o apoio à teoria do direito divino dos reis, a intolerância religiosa e a defesa do mercantilismo.', 'a promoção do ateísmo como política de Estado e a abolição completa da propriedade privada das terras.', 'a restauração do poder político e espiritual da Igreja Católica sobre os monarcas protestantes europeus.', 'a exaltação do trabalho servil nos feudos e a oposição radical aos avanços tecnológicos industriais.', 'a', 'Os pensadores iluministas (Rousseau, Locke, Voltaire) criticavam o Antigo Regime (absolutismo + mercantilismo + Igreja), defendendo a razão, as liberdades individuais, a igualdade jurídica e o livre mercado.', 'fácil', 0],
    [108, 'UNICAMP 2023', 'A Primeira Revolução Industrial (século XVIII) começou na Inglaterra impulsionada por diversos fatores. Dentre eles, destacam-se os Cercamentos (Enclosures), que causaram:', 'o êxodo rural maciço de camponeses expulsos de terras comunais, fornecendo mão de obra abundante e barata para as indústrias urbanas.', 'a distribuição de terras para pequenos proprietários, fortalecendo a agricultura familiar britânica de exportação.', 'o reflorestamento das áreas desmatadas do interior inglês para garantir lenha aos fornos siderúrgicos.', 'a criação de leis de proteção trabalhista que limitaram a jornada nas fábricas para atrair camponeses.', 'a aliança entre nobres rurais e artesãos para impedir a construção de estradas de ferro sobre suas propriedades.', 'a', 'O cercamento das terras comunais inglesas para criação de ovelhas (lã) gerou grande lucro para a burguesia rural, mas forçou camponeses a migrarem para as cidades, onde viraram o proletariado industrial miserável.', 'médio', 0],
    [108, 'USP (FUVEST) 2021', 'Em sua obra "O Espírito das Leis", o pensador iluminista Montesquieu propôs um modelo político que se tornou base das democracias contemporâneas. Tratava-se da:', 'divisão do poder do Estado em três esferas autônomas e harmônicas: Executivo, Legislativo e Judiciário, para evitar a tirania.', 'criação da figura do "déspota esclarecido", um monarca absolutista assessorado por filósofos.', 'democracia direta, na qual todas as decisões políticas deveriam ser tomadas por plebiscitos populares diários.', 'abolição completa do Estado, defendendo a autogestão anarquista das comunidades de trabalhadores.', 'restauração das corporações de ofício medievais para regular a economia sem a intervenção do rei.', 'a', 'Montesquieu argumentava que "só o poder freia o poder". Ele teorizou a tripartição dos poderes para evitar o abuso absolutista, garantindo que quem legisla, quem executa e quem julga sejam entidades distintas.', 'médio', 0],
    [108, 'UNESP 2020', 'A Segunda Revolução Industrial, ocorrida a partir da segunda metade do século XIX, diferenciou-se da Primeira devido à inovação de matrizes energéticas e setores industriais. As principais bases tecnológicas dessa segunda fase foram:', 'o petróleo, a eletricidade, o motor a combustão e a expansão da indústria química e siderúrgica.', 'o carvão mineral, a máquina a vapor, o tear mecânico e a indústria têxtil algodoeira.', 'a energia nuclear, a microeletrônica, a robótica e a internet.', 'a energia eólica, as manufaturas rudimentares de lã e as rotas marítimas de navegação à vela.', 'o gás natural, a biotecnologia agrícola avançada e o uso de inteligência artificial na manufatura.', 'a', 'Enquanto a 1ª fase (Inglaterra) dependeu de carvão, vapor e tecido, a 2ª fase (EUA, Alemanha, Japão) introduziu o aço, a eletricidade, os derivados de petróleo e inovações em comunicações e transportes (telégrafo, automóveis).', 'fácil', 0],
    [108, 'USP (FUVEST) 2022', 'O Taylorismo e o Fordismo foram métodos de racionalização do trabalho implementados no contexto da expansão do capitalismo industrial. Sobre o Fordismo, é correto afirmar que introduziu:', 'a linha de montagem esteirizada, a padronização maciça da produção (produção em massa) e a fragmentação extrema das tarefas do operário.', 'a polivalência do trabalhador, operando em equipes flexíveis voltadas ao controle de qualidade (just in time).', 'a gestão autônoma do chão de fábrica pelos sindicatos operários, reduzindo a alienação do trabalho.', 'o retorno ao artesanato de alto padrão para atender ao consumo exclusivo de luxo da burguesia monopolista.', 'a eliminação do trabalho humano através da automação robótica completa nas indústrias automobilísticas de Detroit.', 'a', 'Henry Ford aplicou a esteira rolante: o trabalho vai até o operário. Ele fabrica um único modelo de carro em massa, baixando o custo. O operário realiza apenas um movimento repetitivo o dia todo (alta alienação).', 'difícil', 1],

    // [109] Primeira e Segunda Guerra Mundial
    [109, 'ENEM 2023', 'A eclosão da Primeira Guerra Mundial (1914-1918) teve como estopim o assassinato do arquiduque austríaco Francisco Ferdinando, ocorrido em Sarajevo. Esse evento pontual desencadeou o conflito porque:', 'acionou um complexo sistema de alianças militares defensivas (Tríplice Entente e Tríplice Aliança) construído pelas potências imperialistas.', 'comprovou a invasão da França pelas tropas russas, forçando a Inglaterra a intervir para proteger Paris.', 'causou o afundamento dos navios mercantes norte-americanos na costa da Europa pela Alemanha.', 'gerou a revolta armada dos bolcheviques comunistas contra os impérios capitalistas ocidentais.', 'destruiu o Tratado de Versalhes recém-assinado, que limitava o tamanho dos exércitos europeus.', 'a', 'A morte do herdeiro austríaco pelas mãos de um nacionalista sérvio levou a Áustria a declarar guerra à Sérvia. Devido à política de alianças, a Rússia apoiou a Sérvia, a Alemanha apoiou a Áustria, e França/Inglaterra entraram em seguida.', 'fácil', 0],
    [109, 'UNICAMP 2021', 'O Tratado de Versalhes (1919), assinado após a Primeira Guerra Mundial, impôs severas sanções à Alemanha. Entre suas exigências, incluía-se:', 'a devolução da Alsácia-Lorena à França, a redução drástica de seu exército e o pagamento de indenizações bilionárias aos vencedores.', 'a divisão do território alemão em duas nações (Alemanha Oriental comunista e Ocidental capitalista).', 'a formação de uma aliança militar obrigatória entre a Alemanha e o Império Otomano sob supervisão dos Estados Unidos.', 'o perdão total de todas as dívidas de guerra visando a reconstrução econômica pacífica da Europa Central.', 'a anexação de todos os portos russos do Báltico pela Marinha britânica como garantia de paz.', 'a', 'O Tratado de Versalhes foi punitivo ("Diktat"). A Alemanha perdeu colônias e territórios europeus, foi desmilitarizada e obrigada a pagar reparações absurdas, gerando ressentimento, miséria e revanchismo que facilitaram o nazismo.', 'médio', 0],
    [109, 'USP (FUVEST) 2020', 'O avanço do nazi-fascismo na Europa nos anos 1930 encontrou pouca resistência inicial devido à Política de Apaziguamento liderada pela Inglaterra e França. Essa política consistia em:', 'ceder gradualmente às exigências territoriais de Hitler (como a anexação da Áustria e dos Sudetos tchecos) na esperança de evitar uma nova grande guerra.', 'financiar secretamente o exército de Mussolini para que atacasse as bases comunistas na União Soviética.', 'bloquear comercialmente todas as importações alemãs e italianas por meio da Liga das Nações.', 'apoiar a facção republicana comunista na Guerra Civil Espanhola contra os aliados de Franco e Hitler.', 'permitir a criação de um Estado judaico soberano na Palestina como compensação pelas perseguições nazistas.', 'a', 'Traumatizados pela 1ª Guerra e temendo mais o avanço do comunismo soviético do que o nazismo, britânicos e franceses toleraram as violações do Tratado de Versalhes feitas por Hitler até a invasão da Polônia em 1939.', 'médio', 0],
    [109, 'UNESP 2022', 'A Segunda Guerra Mundial (1939-1945) foi decidida, em grande parte, pelas campanhas no front oriental. A batalha considerada o ponto de virada decisivo para a derrota da Alemanha nazista na Europa foi:', 'a Batalha de Stalingrado, onde as forças da União Soviética derrotaram e destruíram o 6º Exército alemão, iniciando a contraofensiva russa.', 'o Desembarque na Normandia (Dia D), que ocorreu no primeiro ano da guerra e expulsou rapidamente os alemães da França.', 'a Batalha de Midway, no Pacífico, onde a marinha inglesa dizimou a força aérea nazista.', 'a Batalha da Grã-Bretanha, que impediu o avanço das tropas soviéticas em direção a Londres.', 'o ataque a Pearl Harbor, que aniquilou simultaneamente as esquadras italiana, alemã e japonesa.', 'a', 'Stalingrado (1942-1943) foi a batalha mais sangrenta da história. O rigoroso inverno russo e a tenacidade soviética destruíram as melhores tropas de Hitler, virando o rumo da guerra e forçando a Alemanha a recuar até Berlim.', 'fácil', 0],
    [109, 'USP (FUVEST) 2024', 'O uso das bombas atômicas sobre Hiroshima e Nagasaki (agosto de 1945) pelos Estados Unidos causou controvérsias históricas. No contexto geopolítico do fim da Segunda Guerra, o lançamento visava não apenas forçar a rendição do Japão, mas principalmente:', 'demonstrar supremacia militar inquestionável e intimidar a União Soviética no momento em que se desenhava a Guerra Fria.', 'testar os efeitos da radiação em alvos civis europeus como retaliação direta pelos horrores dos campos de concentração de Auschwitz.', 'impedir que o Japão finalizasse seu próprio programa de armamento nuclear que ameaçava diretamente a costa oeste americana.', 'cumprir os acordos secretos estabelecidos com Stalin na Conferência de Yalta para dividir o arquipélago japonês meio a meio.', 'forçar a China comunista de Mao Tsé-Tung a recuar na invasão territorial coreana iniciada em 1944.', 'a', 'O Japão já estava militarmente estrangulado. O uso da bomba atômica foi uma clara demonstração de poder hegêmonico dos EUA ("diplomacia atômica") para conter a influência de Stalin no pós-guerra na Ásia.', 'difícil', 1],

    // [110] Guerra Fria e Conflitos Contemporâneos
    [110, 'ENEM 2021', 'A Guerra Fria (1947-1991) foi marcada por um conflito político-ideológico indireto entre EUA e URSS. Uma de suas principais características foi a "Corrida Armamentista", que significou:', 'o acúmulo sem precedentes de arsenais nucleares pelas duas superpotências, criando o "equilíbrio do terror" que evitou o confronto militar direto.', 'a doação maciça de armas convencionais aos países do Terceiro Mundo em troca de redução de tarifas de exportação.', 'o desarmamento progressivo dos países da OTAN em prol da assinatura de tratados de paz duradouros sugeridos pela ONU.', 'a substituição completa de tanques e tropas terrestres por satélites de espionagem focados exclusivamente na Guerra nas Estrelas.', 'o fornecimento de tecnologia atômica para o Japão reconstruir rapidamente seu aparato militar defensivo contra a China.', 'a', 'A destruição mútua assegurada (MAD - Mutually Assured Destruction) fez com que nem EUA nem URSS ousassem atacar um ao outro diretamente com bombas atômicas, transferindo os conflitos para áreas periféricas (Vietnã, Coreia).', 'fácil', 0],
    [110, 'UNICAMP 2022', 'O Plano Marshall, implementado pelos Estados Unidos em 1947, consistiu fundamentalmente em:', 'um programa de ajuda financeira maciça para a reconstrução dos países da Europa Ocidental, visando barrar a influência comunista e criar mercados consumidores para produtos americanos.', 'uma aliança militar exclusiva com os países sul-americanos para impedir revoluções socialistas financiadas por Cuba.', 'um boicote econômico total imposto ao bloco soviético, proibindo as exportações agrícolas globais para Moscou.', 'o financiamento do programa espacial americano em resposta ao sucesso soviético do satélite Sputnik.', 'a criação da Organização das Nações Unidas (ONU) e de seus tribunais internacionais de direitos humanos.', 'a', 'Os EUA injetaram bilhões de dólares na Europa devastada (Plano Marshall) para que a miséria pós-guerra não empurrasse a população para o comunismo soviético, garantindo a esfera de influência capitalista americana na região.', 'médio', 0],
    [110, 'USP (FUVEST) 2023', 'A Crise dos Mísseis em Cuba (1962) é considerada o momento mais tenso da Guerra Fria, em que o mundo esteve mais próximo de um holocausto nuclear. O episódio foi gerado:', 'pela instalação secreta de mísseis balísticos nucleares soviéticos na ilha de Cuba em resposta à presença de mísseis americanos na Turquia e Itália.', 'pela invasão de Cuba por fuzileiros navais americanos na Baía dos Porcos com uso ostensivo de armamento radioativo.', 'pelo abate de um avião comercial americano pelos radares soviéticos localizados em Havana.', 'pela recusa de Fidel Castro em exportar urânio enriquecido para as usinas termelétricas soviéticas na Ucrânia.', 'pelo bloqueio naval soviético à ilha de Porto Rico, território não incorporado dos Estados Unidos.', 'a', 'Em 1962, os EUA descobriram que a URSS instalava ogivas nucleares em Cuba (a 150 km da Flórida). Kennedy decretou bloqueio naval à ilha. Após 13 dias de tensão extrema, Kruschev recuou e retirou os mísseis em troca dos EUA retirarem os mísseis de Júpiter na Turquia.', 'médio', 0],
    [110, 'UNESP 2021', 'A descolonização da África e da Ásia ocorreu massivamente nas décadas pós-Segunda Guerra. A Conferência de Bandung (1955), na Indonésia, foi um marco desse processo por:', 'reunir líderes de países recém-independentes para declarar neutralidade (Não-Alinhamento) em relação às superpotências da Guerra Fria e condenar o imperialismo.', 'organizar um exército asiático unificado patrocinado por Moscou para expulsar tropas inglesas do continente.', 'aprovar o Tratado de Não Proliferação Nuclear que impediu países africanos de adquirirem urânio enriquecido.', 'estabelecer o apartheid na África do Sul como modelo de desenvolvimento econômico sustentável.', 'declarar a união de todas as colônias portuguesas da África sob um único governo autônomo e socialista.', 'a', 'Em Bandung, os países asiáticos e africanos originaram o termo "Terceiro Mundo" e o Movimento dos Não Alinhados, rejeitando subordinar-se aos ditames de Washington ou de Moscou e lutando contra o colonialismo remanescente.', 'fácil', 0],
    [110, 'USP (FUVEST) 2024', 'O conflito árabe-israelense é uma das questões contemporâneas mais duradouras. A Guerra dos Seis Dias, ocorrida em 1967, alterou radicalmente a geopolítica do Oriente Médio porque:', 'resultou na vitória fulminante de Israel, que ocupou militarmente a Península do Sinai, a Faixa de Gaza, a Cisjordânia, Jerusalém Oriental e as Colinas de Golã.', 'foi a primeira guerra ganha pela coalizão árabe do Egito e Síria, forçando Israel a recuar às fronteiras originais de 1948 estabelecidas pela ONU.', 'marcou a fundação da Organização para a Libertação da Palestina (OLP) que conseguiu imediato reconhecimento territorial da Liga Árabe no Líbano.', 'culminou no uso de armas químicas e nucleares no Deserto de Negev pelas tropas britânicas de pacificação.', 'encerrou-se com os Acordos de Camp David promovidos pelos EUA, garantindo a criação de um Estado Palestino soberano imediato.', 'a', 'Em apenas seis dias, Israel desferiu ataques preventivos e esmagou os exércitos do Egito, Síria e Jordânia, triplicando seu território controlado e iniciando a longa ocupação militar das áreas onde habitam os palestinos (Gaza e Cisjordânia).', 'difícil', 1],

    // [111] Geomorfologia, Relevo e Solos do Brasil
    [111, 'ENEM 2022', 'O relevo brasileiro é caracterizado por formações antigas, muito desgastadas pela erosão. Segundo a classificação de Jurandyr Ross, o tipo de relevo que ocupa maior área no Brasil são:', 'os planaltos, áreas onde os processos de erosão superam os de deposição de sedimentos.', 'as planícies, extensas áreas alagáveis formadas exclusivamente por intensa atividade tectônica recente.', 'as cordilheiras de dobramentos modernos, como os Andes, presentes nas fronteiras oeste do Brasil.', 'as depressões absolutas, áreas que estão significativamente abaixo do nível do mar, como no interior do Nordeste.', 'os crátons vulcânicos ativos que moldam constantemente a superfície na região sul.', 'a', 'Jurandyr Ross dividiu o Brasil em Planaltos (onde há mais desgaste/erosão), Depressões Relativas (áreas mais rebaixadas que o entorno) e Planícies (onde há mais acúmulo/sedimentação). Não há depressão absoluta nem montanhas recentes no Brasil.', 'fácil', 0],
    [111, 'UNICAMP 2023', 'No interior do Nordeste brasileiro ocorre o fenômeno da desertificação em algumas áreas. Esse processo de degradação ambiental do solo está intimamente ligado a:', 'práticas agrícolas inadequadas, desmatamento contínuo da Caatinga e superpastoreio em uma região de clima semiárido, acelerando a perda de nutrientes.', 'uma intensa atividade vulcânica subterrânea que resseca as nascentes do Rio São Francisco na Bahia.', 'ao avanço natural de dunas de areia do litoral que soterram vastas áreas rurais no agreste.', 'ao uso maciço de fertilizantes químicos importados que salinizaram as terras altas da chapada diamantina de forma irreversível.', 'ao aquecimento global que diminuiu em 90% as já raras chuvas no arquipélago de Fernando de Noronha.', 'a', 'A desertificação no Brasil, especialmente no núcleo do Seridó (RN) e em Gilbués (PI), é um processo antrópico (causado pelo homem) que agrava a fragilidade dos solos rasos do clima semiárido, deixando-os estéreis.', 'médio', 0],
    [111, 'USP (FUVEST) 2021', 'Os solos brasileiros, em sua maioria, são considerados latossolos. Do ponto de vista agronômico, uma característica marcante desses solos no bioma Cerrado é:', 'sua elevada acidez e toxicidade por alumínio, o que exigiu o emprego de técnicas de calagem (aplicação de calcário) para viabilizar a expansão agrícola moderna.', 'sua extrema fertilidade natural oriunda de rochas vulcânicas recentes, dispensando o uso de fertilizantes químicos na produção de soja.', 'seu caráter hidromórfico profundo, estando alagados a maior parte do ano, o que inviabiliza totalmente a mecanização agrária.', 'a presença abundante de terra roxa altamente fértil e basáltica em toda a região Centro-Oeste.', 'serem compostos apenas por areias quartzosas incapazes de reter qualquer tipo de água ou nutriente, configurando desertos inabitáveis.', 'a', 'Os solos do Cerrado são velhos, profundos, bem drenados, porém muito ácidos. A Revolução Verde nos anos 1970 introduziu a técnica da calagem, neutralizando a acidez e tornando o Centro-Oeste a potência do agronegócio que é hoje.', 'médio', 0],
    [111, 'UNESP 2024', 'O Aquífero Guarani é uma das mais importantes reservas subterrâneas de água doce do mundo. Sobre sua localização e estrutura geológica, é correto dizer que ele se encontra associado:', 'à Bacia Sedimentar do Paraná, preenchendo os poros de rochas areníticas cobertas por derrames basálticos e se estendendo pelo sul/sudeste do Brasil e países vizinhos.', 'ao escudo cristalino das Guianas, sob rochas graníticas extremamente duras e impermeáveis no norte da Amazônia.', 'aos dobramentos modernos da cadeia andina ocidental, sendo alimentado diretamente pelo derretimento de geleiras.', 'à planície costeira nordestina, sofrendo risco agudo e imediato de contaminação por intrusão de água do mar devido à superexploração.', 'às depressões sertanejas interplanálticas, constituindo os famosos rios voadores que geram as secas periódicas.', 'a', 'O Guarani é um aquífero poroso (rocha arenito Botucatu/Pirambóia) situado na Bacia do Paraná. Ocupa SP, PR, SC, RS, MS, GO, MT, e partes do Paraguai, Uruguai e Argentina. O aquífero Alter do Chão (Norte) é maior em volume, mas o Guarani é mais extenso.', 'fácil', 0],
    [111, 'USP (FUVEST) 2022', 'O intemperismo (ou meteorização) é o conjunto de processos físicos, químicos ou biológicos que alteram as rochas na superfície terrestre. No Brasil, o principal tipo de intemperismo responsável pela formação de solos profundos, como na Floresta Amazônica, é o:', 'intemperismo químico, favorecido pelas altíssimas temperaturas e elevado volume de chuvas (clima equatorial úmido) que aceleram a decomposição dos minerais das rochas.', 'intemperismo físico, provocado pela grande variação térmica diária (termoclastia) típica das áreas desérticas de Roraima.', 'intemperismo biológico exclusivo de raízes arbustivas, que quebram mecanicamente enormes blocos de granito intactos no fundo dos rios amazônicos.', 'intemperismo glacial, remanescente da última era do gelo que escavou fiordes profundos na bacia do rio Solimões.', 'intemperismo eólico, em que ventos alísios extremamente fortes lapidam contínua e exclusivamente o Planalto das Guianas.', 'a', 'Água e calor aceleram reações químicas. Em climas quentes e úmidos (equatorial e tropical), a rocha apodrece rapidamente pela ação da água (intemperismo químico hidrólise e oxidação), formando solos espessos.', 'difícil', 1],

    // [112] Climatologia e Domínios Morfoclimáticos
    [112, 'ENEM 2021', 'O Domínio Morfoclimático da Caatinga, classificado pelo geógrafo Aziz Ab\'Sáber, caracteriza-se pela interação de elementos físicos marcantes. Assinale a alternativa que descreve corretamente as características dessa região:', 'Clima semiárido com baixos índices pluviométricos, rios intermitentes (temporários) e vegetação xerófila adaptada à escassez de água.', 'Clima subtropical, com chuvas bem distribuídas o ano todo, relevo de mares de morros e vegetação rasteira como as gramíneas pampianas.', 'Clima equatorial, relevo de planície inundável com rede hidrográfica perene e densa e vegetação ombrófila perenifólia gigante.', 'Clima tropical de altitude, com frequentes geadas invernais e vegetação composta exclusivamente por pinheiros de araucária.', 'Clima tropical úmido, restingas arenosas extensas banhadas por manguezais sob intensa ação das marés atlânticas.', 'a', 'A Caatinga ocorre no sertão nordestino. As plantas perdem as folhas na seca (caducifólias), têm raízes profundas e espinhos (xerófilas). Os rios secam nos meses sem chuva (intermitentes/temporários), exceto o São Francisco.', 'fácil', 0],
    [112, 'UNICAMP 2024', 'O clima do Sul do Brasil, que abrange Paraná, Santa Catarina e Rio Grande do Sul, diferencia-se do restante do país. A característica climática fundamental dessa região é:', 'o clima subtropical, apresentando chuvas bem distribuídas ao longo dos meses e quatro estações do ano com maior amplitude térmica anual, incluindo invernos rigorosos.', 'o clima tropical de monções, com seis meses de chuvas torrenciais ininterruptas e seis meses de seca absoluta causados por massas asiáticas.', 'a presença de um deserto de alta altitude nos pampas causado pelo efeito orográfico da Serra do Mar e da Mantiqueira.', 'o predomínio da Massa Equatorial Continental (mEc), que mantém a região abafada e seca ininterruptamente o ano inteiro.', 'o clima temperado continental extremo, com precipitação exclusiva em forma de neve durante cinco meses do ano.', 'a', 'Abaixo do Trópico de Capricórnio atua o clima Subtropical (Massas Polar Atlântica e Tropical Atlântica). Chove o ano todo (não há estação seca definida) e as temperaturas no inverno caem bastante, gerando a maior amplitude térmica do país.', 'médio', 0],
    [112, 'USP (FUVEST) 2020', 'O fenômeno climático "El Niño" refere-se ao aquecimento anormal das águas do Oceano Pacífico Equatorial. No Brasil, os efeitos clássicos desse fenômeno manifestam-se, tipicamente, por:', 'secas severas prolongadas na região Norte e Nordeste, e chuvas muito acima da média na região Sul, causando frequentes inundações.', 'invernos glaciais rigorosos em toda a região Nordeste e aumento da temperatura no Sul acima de 45°C.', 'furacões devastadores de categoria 5 atingindo diretamente o litoral sudeste entre São Paulo e Rio de Janeiro todo verão.', 'o aumento na intensidade das chuvas no sertão nordestino que garantem safras agrícolas recordes sem uso de irrigação.', 'a formação do fenômeno da "friagem" diária na Amazônia devido ao fortalecimento desproporcional da massa Equatorial Atlântica.', 'a', 'O El Niño altera os padrões de ventos em escala global. No Brasil, ele bloqueia frentes frias no Sul (gerando chuvas torrenciais no RS/SC/PR) e inibe a formação de chuvas no Norte/Nordeste (agravando secas).', 'médio', 0],
    [112, 'UNESP 2022', 'No estado de São Paulo e Minas Gerais, a ocorrência de chuvas orográficas (ou de relevo) é muito comum. Esse tipo de precipitação acontece quando:', 'uma massa de ar úmida vinda do oceano encontra uma barreira montanhosa (como a Serra do Mar), é forçada a subir, resfria-se, condensa e chove na encosta barlavento.', 'duas massas de ar com temperaturas diametralmente opostas colidem violentamente no interior do continente formando chuvas frontais e tornados.', 'o intenso calor das tardes de verão provoca a evaporação rápida de rios e lagos urbanos, gerando pesadas chuvas convectivas de curta duração.', 'o resfriamento rápido noturno de uma área plana forma neblinas densas e geadas severas nas madrugadas de inverno sem qualquer vento.', 'ventos secos vindos do interior do país empurram nuvens cúmulos para o mar aberto, descarregando água salobra sobre os litorais nordestinos.', 'a', 'A umidade do mar (Massa Tropical Atlântica) bate na Serra do Mar, sobe e esfria. A chuva orográfica deságua quase toda no litoral (barlavento), e o ar passa seco e quente para o outro lado do relevo (sotavento).', 'fácil', 0],
    [112, 'USP (FUVEST) 2023', 'As chamadas "ilhas de calor" são anomalias microclimáticas típicas de grandes metrópoles, como São Paulo. Sua causa principal e efeito prático, respectivamente, são:', 'a alta impermeabilização do solo pelo asfalto e a escassez de vegetação associada a edifícios, retendo calor e gerando temperaturas maiores no centro urbano em relação à periferia.', 'a inversão térmica no inverno, onde o ar quente aprisiona os poluentes próximos ao solo, causando frio extremo e neblina ácida crônica.', 'a destruição da camada de ozônio causada pelas chaminés industriais, que derrete as calotas de gelo locais nos parques da cidade.', 'o albedo elevadíssimo dos telhados brancos dos prédios de luxo que reflete a radiação, esfriando drasticamente as ruas marginais aos rios poluídos.', 'a convecção excessiva de ar frio dos pátios de fábricas abandonadas que atrai frentes frias antárticas violentas fora de época.', 'a', 'O asfalto e concreto absorvem muito calor do sol durante o dia. A falta de árvores e o excesso de carros/prédios fazem com que a zona central (mais urbanizada) fique até 5 a 10°C mais quente que as áreas rurais no entorno (ilhas de calor).', 'difícil', 1],

    // [113] Hidrografia e Bacias Hidrográficas
    [113, 'ENEM 2023', 'O Brasil possui uma das maiores e mais complexas redes hidrográficas do planeta. Uma característica marcante da hidrografia brasileira é que a quase totalidade de seus rios:', 'possui regime pluvial (alimentado por chuvas), drenagem exorreica (deságua no mar) e foz em estuário.', 'apresenta regime nival (alimentado por derretimento de neve) nas nascentes, desaguando em lagos tectônicos internos.', 'é do tipo endorreico, não alcançando o oceano e perdendo-se no interior árido do continente, formando aquíferos superficiais.', 'corre no sentido do Equador e deságua em deltas ramificados e complexos como o do rio Parnaíba em toda sua costa.', 'é composta por bacias arreicas temporárias no Sudeste, que secam no verão devido ao fenômeno da evapotranspiração acelerada das monoculturas.', 'a', 'Os rios brasileiros dependem das águas das chuvas (pluviais, exceto o rio Amazonas que também é nival nos Andes). Eles correm para o Oceano Atlântico (exorreicos) e a maioria desemboca num único canal para o mar (estuário).', 'fácil', 0],
    [113, 'UNICAMP 2022', 'A bacia hidrográfica do rio São Francisco, popularmente conhecido como "Velho Chico", é vital para a integração nacional. A sua grande importância econômica e social deve-se, entre outros fatores, a:', 'ser um rio perene que corta a região semiárida, possibilitando projetos de irrigação e geração de energia hidrelétrica (como as usinas de Sobradinho e Xingó).', 'seu papel exclusivo na hidrovia de exportação de soja, permitindo a navegação de grandes cargueiros transoceânicos de Minas Gerais até a Europa.', 'ser o único rio de planície totalmente retilíneo que fornece água potável e doce, sem tratamento, para todas as capitais litorâneas nordestinas.', 'sua nascente localizada nos Andes garantir um fluxo hídrico inesgotável independentemente do índice de chuvas locais no Brasil.', 'ao seu curso subterrâneo que atravessa o sertão baiano aflorando exclusivamente em oásis termais protegidos por lei federal.', 'a', 'O rio São Francisco nasce na Serra da Canastra (MG), tem regime pluvial perene e atravessa o polígono das secas (sertão). Fornece água para consumo humano, irrigação de fruticultura (como Petrolina/Juazeiro) e possui complexos hidrelétricos.', 'médio', 0],
    [113, 'USP (FUVEST) 2020', 'O Aquífero Alter do Chão (Sistema Aquífero Grande Amazônia) foi alvo de estudos recentes que comprovaram tratar-se do maior reservatório de água subterrânea do Brasil em volume de água. Ele difere do Aquífero Guarani em qual aspecto geológico/geográfico essencial?', 'Está situado quase inteiramente nos estados do Amazonas, Pará e Amapá, sob densa cobertura florestal, apresentando volumes aquíferos muito superiores devido à alta pluviosidade amazônica.', 'Apresenta águas fortemente salinas que exigem caros processos de dessalinização reversa antes de uso humano em Manaus.', 'Suas reservas estão completamente inacessíveis em falhas geológicas tectônicas a mais de dez mil metros de profundidade da crosta.', 'Foi exaurido quase completamente pelo agronegócio exportador de algodão de Rondônia na última década.', 'É classificado como um lençol freático superficial restrito exclusivamente a uma estreita faixa de areia na planície litorânea maranhense.', 'a', 'O Alter do Chão (Norte) é arenoso e mais espesso/profundo que o Guarani. Como chove demais na Amazônia, a recarga é monumental. Em volume d\'água, o Alter do Chão supera em muito o Guarani, embora este último seja mais extenso.', 'médio', 0],
    [113, 'UNESP 2023', 'A Bacia Amazônica é a maior bacia hidrográfica do mundo em volume de água e extensão. O relevo dessa bacia proporciona enorme potencial hidroelétrico no Brasil. Esse potencial encontra-se concentrado em:', 'nos seus rios afluentes de planalto (como o Madeira, Tocantins, Xingu), que possuem grandes desníveis e corredeiras perfeitos para barragens.', 'na calha principal do próprio rio Amazonas, que percorre degraus de mais de mil metros entre Manaus e Belém gerando quedas gigantescas.', 'em furos e paranás no delta do rio que aproveitam a força natural violenta e diária do encontro fluvial com a pororoca marinha atlântica.', 'exclusivamente nas nascentes glaciais dos Andes peruanos, onde empresas binacionais administram a captação gravitacional profunda.', 'em lagos temporários de várzea durante os meses de julho que estocam energia potencial por gravidade suspensa em meandros abandonados.', 'a', 'O rio Amazonas é de planície (excelente para navegação). O grande potencial hidrelétrico (como Belo Monte, Tucuruí, Jirau) está em seus afluentes (rios de planalto, com declive, que nascem nos escudos cristalinos das Guianas e do Brasil).', 'fácil', 0],
    [113, 'USP (FUVEST) 2024', 'O desastre ambiental da bacia do Rio Doce (2015), com o rompimento da barragem de Fundão (Mariana, MG), gerou impactos hidrológicos em cascata até o oceano. Do ponto de vista ecossistêmico e limnológico, a lama de rejeitos de minério provocou:', 'o assoreamento severo das calhas dos rios, drástico aumento da turbidez da água que impediu a fotossíntese do fitoplâncton e a asfixia massiva da ictiofauna e bentos.', 'a eutrofização instantânea da água por superabundância de fertilizantes fosfatados gerando rápida e inofensiva floração de algas verdes gigantes costeiras.', 'a elevação permanente do lençol freático adjacente, que converteu terras agrícolas secas em pântanos altamente produtivos para orizicultura na planície do Espírito Santo.', 'a acidificação letal da bacia com ph igual a 2.0, dissolvendo imediatamente pontes de concreto armado e embarcações ancoradas em linha reta até Colatina.', 'o fim definitivo e provado da evapotranspiração no vale do Rio Doce reduzindo em 90% as chuvas em toda a Região Sudeste do país.', 'a', 'A lama tóxica e espessa de minério de ferro soterrou o fundo do rio (matando peixes e bentos), barrou a entrada de luz solar (impedindo a fotossíntese na água) e comprometeu o abastecimento público de centenas de municípios.', 'difícil', 1],

    // [114] Urbanização, Demografia e Migrações
    [114, 'ENEM 2022', 'O processo de urbanização brasileira ocorreu de maneira rápida, desordenada e concentrada a partir do século XX. O fator fundamental que impulsionou a forte migração campo-cidade (êxodo rural) foi:', 'a industrialização acelerada do Sudeste (pólo de atração) combinada à mecanização agrícola e concentração fundiária no campo (pólos de repulsão).', 'a política sistemática de reforma agrária federal que comprou minifúndios e os transformou em indústrias estatais no interior nordestino.', 'a descoberta das grandes minas de ouro em São Paulo no início dos anos 1950, atraindo populações carentes do sul rural.', 'as grandes epidemias de cólera e febre amarela que forçaram o despovoamento repentino do interior produtivo agropecuário.', 'o incentivo direto de Getúlio Vargas para que todos os trabalhadores rurais abandonassem a CLT do campo e migrassem para as metrópoles.', 'a', 'A modernização conservadora do campo (tratores substituindo enxadas) expulsou o camponês pobre sem terra, que migrou em massa para cidades como SP e RJ na ilusão de conseguir emprego nas fábricas que surgiam ("milagre econômico").', 'fácil', 0],
    [114, 'UNICAMP 2021', 'A "gentrificação" é um fenômeno socioespacial muito estudado nas grandes metrópoles. Na prática, esse conceito descreve:', 'a revitalização de áreas urbanas antes degradadas, que valoriza intensamente os imóveis e expulsa a população de baixa renda original para as periferias.', 'a construção subsidiada pelo Estado de conjuntos habitacionais populares em bairros nobres e consolidados, democratizando o acesso à moradia.', 'a decadência absoluta e abandono irreversível de centros históricos tomados por comércios informais que derrubam o IPTU da zona.', 'o processo natural e espontâneo de criação de favelas íngremes em encostas de morros por invasões coletivas noturnas sem qualquer planejamento.', 'a conversão de fábricas industriais sujas da década de 1970 em grandes fazendas verticais comunitárias para agricultores urbanos.', 'a', 'A gentrificação (do inglês "gentry", nobreza) é o "enobrecimento" de um bairro. O mercado imobiliário reforma o local, os aluguéis e os serviços encarecem muito, forçando os antigos moradores mais pobres a saírem por não conseguirem pagar o novo custo de vida.', 'médio', 0],
    [114, 'USP (FUVEST) 2023', 'A transição demográfica brasileira encontra-se em estágio avançado. Analisando as pirâmides etárias das últimas décadas do IBGE, constata-se uma alteração profunda no perfil populacional, caracterizada por:', 'estreitamento contínuo da base (queda da taxa de natalidade/fecundidade) e alargamento progressivo do topo e centro (aumento da expectativa de vida e envelhecimento).', 'um drástico alargamento da base, reflexo do aumento explosivo do número de nascimentos a partir do ano 2000.', 'o formato cilíndrico perfeito, indicando taxas altíssimas de mortalidade infantil compensadas imediatamente por imigrantes jovens venezuelanos.', 'a redução acentuada do topo devido a surtos recentes de pandemias mortais e estagnação crônica e permanente da classe média no meio urbano.', 'uma queda abrupta e imediata na População Economicamente Ativa (PEA) causada exclusivamente pelo incentivo governamental ao celibato voluntário generalizado.', 'a', 'O Brasil teve uma rápida urbanização, popularização dos anticoncepcionais e maior inserção da mulher no mercado de trabalho, derrubando a fecundidade. Com a medicina, o idoso vive mais. A pirâmide brasileira deixou de ser um triângulo gordo e caminha para o formato de "barril".', 'médio', 0],
    [114, 'UNESP 2020', 'No final do século XX e início do XXI, notou-se uma mudança no padrão migratório interno no Brasil. O movimento predominante anterior de nordestinos para o Sudeste foi, em certa medida, substituído por um novo fenômeno demográfico e econômico conhecido como:', 'migração de retorno, impulsionada pelo desenvolvimento de novos polos econômicos regionais no Nordeste e pela desconcentração industrial das metrópoles sudestinas.', 'migração transumante definitiva para a Amazônia Legal com o fim total das terras disponíveis em Mato Grosso e São Paulo.', 'êxodo metropolitano internacional, com esvaziamento drástico e repentino das cidades médias do interior paulista para a Europa Ocidental.', 'migração pendular intra-regional nordestina exclusiva em direção a áreas produtoras de cacau e sisal decadentes no interior baiano.', 'nomadismo rural de subsistência, onde populações paulistas desempregadas invadem e migram mensalmente entre as antigas fazendas escravistas fluminenses.', 'a', 'A partir dos anos 1990/2000, o Sudeste ficou caro e saturado. Com incentivos fiscais e expansão do setor de serviços/construção civil no Nordeste, muitos migrantes ou seus filhos começaram a voltar para o Nordeste (migração de retorno).', 'fácil', 0],
    [114, 'USP (FUVEST) 2024', 'O bônus demográfico (ou janela demográfica) é uma condição temporária e muito favorável ao desenvolvimento econômico de um país. O Brasil atingiu seu momento de bônus demográfico nas últimas décadas, mas as projeções alertam para o seu iminente fechamento. Esse fechamento implicará desafios colossais, tais como:', 'o aumento da razão de dependência demográfica, onde a proporção de idosos cresce em relação à População Economicamente Ativa (PEA), pressionando o sistema de saúde público e a sustentabilidade previdenciária.', 'a explosão incontrolável da taxa de fecundidade juvenil urbana e a exigência de construir milhares de creches simultâneas em menos de cinco anos para sustentar mães operárias.', 'a fuga em massa dos melhores cérebros científicos para o exterior e a falta absoluta de recém-nascidos inviabilizando matematicamente a convocação militar nacional obrigatória.', 'a dependência integral das indústrias nacionais frente ao fechamento dos portos e ao declínio total da agricultura familiar agroecológica da região sul-sudeste.', 'o encerramento das vagas em universidades públicas devido ao número zero de jovens completando o ensino médio nos próximos 15 anos consecutivos.', 'a', 'Bônus demográfico é quando há mais gente em idade de trabalhar (PEA) do que de dependentes (crianças e idosos). Quando a janela fecha, a população envelhece muito e a base de jovens encolhe, quebrando os sistemas de aposentadoria se o país não enriqueceu antes (desafio previdenciário).', 'difícil', 1],
];

$stmt = $pdo->prepare("INSERT INTO questions (lesson_id, exam_source, question_text, option_a, option_b, option_c, option_d, option_e, correct_option, explanation_text, difficulty, is_boss) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)");
$inserted = 0;
$errors = 0;
foreach ($questions as $q) {
    try { 
        $stmt->execute($q); 
        $inserted++; 
    } catch (Exception $e) { 
        $errors++; 
        echo "ERRO: " . $e->getMessage() . "\n"; 
    }
}
echo "\nInseridas: {$inserted} | Erros: {$errors}\n";
